struct IndiceFuera {};

class Terna {
public:
    Terna() = default;
    Terna(int primero, int segundo, int tercero) : datos_{primero, segundo, tercero} {}
    int& operator[](int indice) &;
    const int& operator[](int indice) const &;
    int operator[](int indice) &&;
    int operator[](int indice) const &&;
    void escribir(std::ostream& salida) const {
        salida << datos_[0] << ':' << datos_[1] << ':' << datos_[2];
    }
private:
    int datos_[3]{10, 20, 30};
};
int& Terna::operator[](int indice) & {
    if (indice < 0 || indice >= 3) { throw IndiceFuera{}; }
    return datos_[indice];
}
const int& Terna::operator[](int indice) const & {
    if (indice < 0 || indice >= 3) { throw IndiceFuera{}; }
    return datos_[indice];
}
int Terna::operator[](int indice) && {
    // Comprueba el índice y devuelve una copia del int elegido.
    (void)indice;
    return 0;
}

int Terna::operator[](int indice) const && {
    // Mantén la misma comprobación y copia en el acceso rvalue constante.
    (void)indice;
    return 0;
}

int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) { return 1; }
    Terna datos;
    const Terna& lectura = datos;
    int guardado = -7;

    for (int i = 0; i < ordenes; ++i) {
        int op = 0, indice = 0, valor = 0;
        if (!(std::cin >> op >> indice >> valor)) { return 1; }
        std::cout << "Antes:";
        datos.escribir(std::cout);
        const char* estado = "Aceptada";
        try {
            if (op == 1) { datos[indice] = valor; }
            else if (op == 2) { guardado = std::move(datos)[indice]; }
            else if (op == 3) { guardado = std::move(lectura)[indice]; }
            else if (op == 4) { guardado = Terna{valor, 41, -6}[indice]; }
            else if (op == 5) {
                const int& independiente = Terna{valor, 41, -6}[indice];
                guardado = independiente;
            } else { estado = "Operacion"; }
        } catch (const IndiceFuera&) { estado = "Indice"; }
        std::cout << ";Estado:" << estado << ";Copia:" << guardado << ";Ahora:";
        datos.escribir(std::cout);
        std::cout << '\n';
    }
    std::cout << "Final:";
    datos.escribir(std::cout);
    std::cout << ";Copia:" << guardado;

    return 0;
}

